(function(root){
const teams=['Service desk','Integrations','Automation'];
const rows=teams.flatMap((team,t)=>Array.from({length:8},(_,i)=>({team,week:i+1,opened:[110,125,119,132,140,155,178,190][i]+t*21,resolved:[112,123,120,130,136,143,150,155][i]+t*24,sla:[96,95,96,94,93,91,87,85][i]+t*2})));
function aggregate(team,period){const n=Number(period);if(![2,4].includes(n)||!['All teams',...teams].includes(team))throw Error('Invalid filter');const scope=rows.filter(r=>team==='All teams'||r.team===team),selected=scope.filter(r=>r.week>8-n),prior=scope.filter(r=>r.week>8-2*n&&r.week<=8-n);const sum=(rs,k)=>rs.reduce((s,r)=>s+r[k],0);const opened=sum(selected,'opened'),resolved=sum(selected,'resolved');return {selected,opened,resolved,sla:selected.reduce((s,r)=>s+r.sla*r.resolved,0)/resolved,change:100*(opened-sum(prior,'opened'))/sum(prior,'opened'),backlog:opened-resolved,rate:100*resolved/opened,weeks:Array.from({length:n},(_,i)=>{const week=9-n+i,rs=selected.filter(r=>r.week===week);return {week,opened:sum(rs,'opened'),resolved:sum(rs,'resolved')};})};}
function classify(input){const s=input.trim();if(s.length<20||s.length>2000)throw Error('Enter between 20 and 2,000 characters.');const rules=[{category:'Service incident',re:/\b(outage|offline|unavailable|down|interruption)\b/i,route:'Service desk',next:'Verify incident scope and escalate to the service owner.'},{category:'Access request',re:/\b(access|permission|account|login)\b/i,route:'Identity team',next:'Verify identity and obtain system owner authorization.'},{category:'Billing inquiry',re:/\b(invoice|billing|payment|refund)\b/i,route:'Finance queue',next:'Validate the invoice through the approved finance process.'}];const matches=rules.filter(r=>r.re.test(s)),r=matches.length===1?matches[0]:{category:'Manual triage',route:'General service queue',next:'Ask a reviewer to clarify the request and select an owner.'};return {category:r.category,priority:/\b(outage|offline|unavailable|urgent|critical)\b/i.test(s)?'High':'Normal',route:r.route,next:r.next,reason:matches.length===1?'Explicit keyword match; human verification required.':'Ambiguous or unmatched request; manual triage required.',draft:`Thank you for your request. We have prepared it for review by the ${r.route}. ${r.next} A team member will confirm next steps. This draft does not confirm that any action has been taken.`};}
const api={rows,aggregate,classify};if(typeof module!=='undefined')module.exports=api;else root.DemoEngine=api;
})(globalThis);
